int process_magic_device_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size) {
    struct magic_drvdata *drvdata = hid_get_drvdata(hdev);
    int report_id = data[0];

    switch (report_id) {
    case TRACKPAD_REPORT_ID: {
        if (size < 12)
            return 0;

        int num_fingers = data[1];
        if (num_fingers > MAX_TOUCHPOINTS)
            num_fingers = MAX_TOUCHPOINTS;

        for (int i = 0; i < num_fingers; i++) {
            struct input_event ev;
            int x = (data[2 + i * 4] << 8) | data[3 + i * 4];
            int y = (data[4 + i * 4] << 8) | data[5 + i * 4];
            input_report_abs(drvdata->input, ABS_MT_POSITION_X, x);
            input_report_abs(drvdata->input, ABS_MT_POSITION_Y, y);
            input_event(drvdata->input, EV_SYN, SYN_MT_REPORT, 0);
        }

        if (data[13] & 0x01)
            input_report_key(drvdata->input, BTN_LEFT, 1);
        else
            input_report_key(drvdata->input, BTN_LEFT, 0);

        break;
    }

    case MOUSE_REPORT_ID: {
        if (size < 6)
            return 0;

        int dx = data[1];
        int dy = data[2];
        int buttons = data[3];

        input_report_rel(drvdata->input, REL_X, dx);
        input_report_rel(drvdata->input, REL_Y, dy);

        input_report_key(drvdata->input, BTN_LEFT, buttons & 0x01);
        input_report_key(drvdata->input, BTN_RIGHT, buttons & 0x02);

        break;
    }

    case DOUBLE_REPORT_ID: {
        if (size < 20)
            return 0;

        int num_fingers = data[1];
        if (num_fingers > MAX_TOUCHPOINTS)
            num_fingers = MAX_TOUCHPOINTS;

        for (int i = 0; i < num_fingers; i++) {
            struct input_event ev;
            int x = (data[2 + i * 4] << 8) | data[3 + i * 4];
            int y = (data[4 + i * 4] << 8) | data[5 + i * 4];
            input_report_abs(drvdata->input, ABS_MT_POSITION_X, x);
            input_report_abs(drvdata->input, ABS_MT_POSITION_Y, y);
            input_event(drvdata->input, EV_SYN, SYN_MT_REPORT, 0);
        }

        int dx = data[10];
        int dy = data[11];
        int buttons = data[12];

        input_report_rel(drvdata->input, REL_X, dx);
        input_report_rel(drvdata->input, REL_Y, dy);

        input_report_key(drvdata->input, BTN_LEFT, buttons & 0x01);
        input_report_key(drvdata->input, BTN_RIGHT, buttons & 0x02);

        break;
    }

    default:
        return 0;
    }

    input_event(drvdata->input, EV_SYN, SYN_REPORT, 0);
    return 1;
}

int process_magic_input_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size)
{
    struct magic_drvdata *drvdata = hid_get_drvdata(hdev);
    int ret = 0;

    if (!drvdata)
        return 0;

    switch (report->id) {
    case TRACKPAD_REPORT_ID:
        if (size < TRACKPAD_MIN_SIZE)
            break;

        ret = process_trackpad_report(hdev, data, size);
        break;

    case MOUSE_REPORT_ID:
        if (size < MOUSE_MIN_SIZE)
            break;

        ret = process_mouse_report(hdev, data, size);
        break;

    case DOUBLE_REPORT_ID:
        if (size < DOUBLE_MIN_SIZE)
            break;

        ret = process_double_report(hdev, data, size);
        break;

    default:
        break;
    }

    if (ret)
        input_sync(drvdata->input);

    return ret ? 1 : 0;
}

