{
    struct magic_drvdata *drv_data = hid_get_drvdata(hdev);
    int ret = 0;

    if (!drv_data)
        return 0;

    switch (data[0]) {
    case TRACKPAD_REPORT_ID:
        if (size < TRACKPAD_MIN_SIZE)
            break;
        ret = process_trackpad_report(drv_data, data, size);
        break;
    case MOUSE_REPORT_ID:
        if (size < MOUSE_MIN_SIZE)
